<template><section class="page"><header><div><h2>维修物料管理</h2><p>管理备件库存、安全库存、成本和出入库记录。</p></div><el-button type="primary" @click="open()">新增物料</el-button></header><el-form class="filters" inline><el-form-item label="关键词"><el-input v-model="keyword" clearable/></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button></el-form-item></el-form><el-table :data="rows" border><el-table-column prop="materialCode" label="物料编码" width="140"/><el-table-column prop="materialName" label="物料名称" min-width="160"/><el-table-column prop="specification" label="规格" min-width="140"/><el-table-column prop="stockQuantity" label="库存" width="90"/><el-table-column prop="reservedQuantity" label="预留" width="90"/><el-table-column prop="availableQuantity" label="可用" width="90"/><el-table-column prop="safetyStock" label="安全库存" width="100"/><el-table-column label="预警" width="85"><template #default="{row}"><el-tag :type="row.lowStock?'danger':'success'">{{row.lowStock?'不足':'正常'}}</el-tag></template></el-table-column><AdaptiveActionColumn label="操作" :width="150"><template #default="{row}"><div class="actions"><el-button link @click="open(row)">编辑</el-button><el-button link type="success" @click="openStock(row)">入库</el-button></div></template></AdaptiveActionColumn></el-table><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="search"/><el-dialog v-model="dialog" :title="form.id?'编辑物料':'新增物料'" width="600px"><el-form label-width="100px"><el-form-item label="物料编码"><el-input v-model="form.materialCode"/></el-form-item><el-form-item label="物料名称"><el-input v-model="form.materialName"/></el-form-item><el-form-item label="规格"><el-input v-model="form.specification"/></el-form-item><el-form-item label="单位"><el-input v-model="form.unit"/></el-form-item><el-form-item label="安全库存"><el-input-number v-model="form.safetyStock" :min="0"/></el-form-item><el-form-item label="单位成本"><el-input-number v-model="form.unitCost" :min="0" :precision="2"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option value="ACTIVE" label="启用"/><el-option value="DISABLED" label="停用"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="stockDialog" title="物料入库" width="480px"><el-form label-width="90px"><el-form-item label="入库数量"><el-input-number v-model="stock.quantity" :min="0.001" :precision="3"/></el-form-item><el-form-item label="备注"><el-input v-model="stock.remark"/></el-form-item></el-form><template #footer><el-button @click="stockDialog=false">取消</el-button><el-button type="primary" @click="restock">确认入库</el-button></template></el-dialog></section></template>
<script setup>
import { onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { createMaterial, materials, restockMaterial, updateMaterial } from '../api'
const rows=ref([]),keyword=ref(''),page=ref(1),size=ref(20),total=ref(0),dialog=ref(false),stockDialog=ref(false),selected=ref(null);const form=reactive({id:'',materialCode:'',materialName:'',specification:'',unit:'个',safetyStock:0,unitCost:0,status:'ACTIVE'});const stock=reactive({quantity:1,remark:''})
const load=async()=>{const r=await materials({keyword:keyword.value,page:page.value-1,size:size.value});rows.value=r.data.content;total.value=r.data.totalElements};const search=()=>{page.value=1;load()};const open=row=>{Object.assign(form,row||{id:'',materialCode:'',materialName:'',specification:'',unit:'个',safetyStock:0,unitCost:0,status:'ACTIVE'});dialog.value=true};const save=async()=>{form.id?await updateMaterial(form.id,form):await createMaterial(form);ElMessage.success('保存成功');dialog.value=false;load()};const openStock=row=>{selected.value=row;Object.assign(stock,{quantity:1,remark:''});stockDialog.value=true};const restock=async()=>{await restockMaterial(selected.value.id,stock);ElMessage.success('入库成功');stockDialog.value=false;load()};onMounted(load)
</script><style scoped>.page{padding:24px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}h2{margin:0 0 6px}p{margin:0;color:#84909a}.filters{margin-bottom:10px}.el-pagination{margin-top:10px;justify-content:flex-end}.actions{display:flex;flex-wrap:nowrap;white-space:nowrap}</style>
